            set
            {
                var emptySecret = Output.CreateSecret(ImmutableDictionary.Create<string, string>());
                _secretHeaders = Output.All(value, emptySecret).Apply(v => v[0]);
            }
        }

        /// <summary>
        /// Present a client certificate during the TLS handshake. Requires an `https://` base URL. Independent of the Authentication method above, so it can be combined with a bearer token, API key, basic auth or OAuth 2.0 client credentials.
        /// </summary>
        [Input("useMtls")]
        public Input<bool>? UseMtls { get; set; }

        /// <summary>
        /// Whether the connector should send all requests from specific static IPs.
        /// </summary>
        [Input("useStaticIps")]
        public Input<bool>? UseStaticIps { get; set; }

        public HttpConnectorState()
        {
        }
        public static new HttpConnectorState Empty => new HttpConnectorState();
    }
}
